#!/usr/bin/env bash
# PreToolUse guard (all agents): src/types/database.ts is generated by `npm run db:types`.
path=$(jq -r '.tool_input.file_path // empty')
if [[ "$path" == */src/types/database.ts ]]; then
  echo "Blocked: src/types/database.ts is generated. Run 'npm run db:types' after migrations." >&2
  exit 2
fi
exit 0
